import type { FreeCamera, SceneContext } from "@babylonjs/lite";
import { attachFreeControl, createFreeCamera } from "@babylonjs/lite";

type Vec = { x: number; y: number; z: number };
type MutableVec = { x: number; y: number; z: number };

export interface Walkthrough { readonly camera: FreeCamera; jumpTo(eye: Vec, target: Vec): void; dispose(): void }

export function createWalkthrough(canvas: HTMLCanvasElement, scene: SceneContext, eye: Vec, target: Vec): Walkthrough {
  const camera = createFreeCamera(eye, target);
  (scene as unknown as { camera: FreeCamera }).camera = camera;

  let detach = attachFreeControl(camera, canvas, scene);
  let disposed = false;

  const setView = (nextEye: Vec, nextTarget: Vec) => {
    const position = camera.position as unknown as MutableVec;
    const lookAt = camera.target as unknown as MutableVec;
    position.x = nextEye.x; position.y = nextEye.y; position.z = nextEye.z;
    lookAt.x = nextTarget.x; lookAt.y = nextTarget.y; lookAt.z = nextTarget.z;

    // Keep internal orientation fields consistent with the new view.
    const orientation = createFreeCamera(nextEye, nextTarget);
    camera._yaw = orientation._yaw;
    camera._pitch = orientation._pitch;
  };

  return {
    camera,
    jumpTo(nextEye, nextTarget) {
      if (disposed) return;
      detach();
      setView(nextEye, nextTarget);
      detach = attachFreeControl(camera, canvas, scene);
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      detach();
    }
  };
}
```
